class Solution {
public:
    int totalStrength(std::vector<int>& strength) {
        long long MOD = 1e9 + 7;
        int n = strength.size();
        std::vector<int> left(n, -1), right(n, n);
        std::vector<int> stk;
        for (int i = 0; i < n; ++i) {
            while (!stk.empty() && strength[stk.back()] >= strength[i]) stk.pop_back();
            left[i] = stk.empty() ? -1 : stk.back();
            stk.push_back(i);
        }
        stk.clear();
        for (int i = n - 1; i >= 0; --i) {
            while (!stk.empty() && strength[stk.back()] > strength[i]) stk.pop_back();
            right[i] = stk.empty() ? n : stk.back();
            stk.push_back(i);
        }
        std::vector<long long> pref(n + 1, 0), pref_pref(n + 2, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = (pref[i] + strength[i]) % MOD;
        for (int i = 0; i <= n; ++i) pref_pref[i + 1] = (pref_pref[i] + pref[i]) % MOD;
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            int L = left[i] + 1, R = right[i] - 1;
            long long left_count = i - L + 1, right_count = R - i + 1;
            long long pos_part = (pref_pref[R + 2] - pref_pref[i + 1] + MOD) % MOD * left_count % MOD;
            long long neg_part = (pref_pref[i + 1] - pref_pref[L] + MOD) % MOD * right_count % MOD;
            long long total_sum = (pos_part - neg_part + MOD) % MOD;
            ans = (ans + strength[i] * total_sum) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int totalStrength(int[] strength) {
        long MOD = 1_000_000_007L;
        int n = strength.length;
        int[] left = new int[n];
        int[] right = new int[n];
        int[] stk = new int[n];
        int top = -1;
        for (int i = 0; i < n; i++) {
            while (top >= 0 && strength[stk[top]] >= strength[i]) top--;
            left[i] = top >= 0 ? stk[top] : -1;
            stk[++top] = i;
        }
        top = -1;
        for (int i = n - 1; i >= 0; i--) {
            while (top >= 0 && strength[stk[top]] > strength[i]) top--;
            right[i] = top >= 0 ? stk[top] : n;
            stk[++top] = i;
        }
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = (pref[i] + strength[i]) % MOD;
        long[] prefPref = new long[n + 2];
        for (int i = 0; i <= n; i++) prefPref[i + 1] = (prefPref[i] + pref[i]) % MOD;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int L = left[i] + 1, R = right[i] - 1;
            long leftCount = i - L + 1, rightCount = R - i + 1;
            long posPart = (prefPref[R + 2] - prefPref[i + 1] + MOD) % MOD * leftCount % MOD;
            long negPart = (prefPref[i + 1] - prefPref[L] + MOD) % MOD * rightCount % MOD;
            long totalSum = (posPart - negPart + MOD) % MOD;
            ans = (ans + (long) strength[i] * totalSum) % MOD;
        }
        return (int) ans;
    }
}

